er image", "tracking": {"current_release_date": "2026-08-02T19:03:04+00:00", "generator": {"date": "2026-08-02T19:03:04+00:00", "engine": {"name": "Red Hat SDEngine", "version": "5.3.8"}}, "id": "RHSA-2026:14870", "initial_release_date": "2026-05-07T15:45:54+00:00", "revision_history": [{"date": "2026-05-07T15:45:54+00:00", "number": "1", "summary": "Initial version"}, {"date": "2026-08-01T08:08:43+00:00", "number": "2", "summary": "Last updated version"}, {"date": "2026-08-02T19:03:04+00:00", "number": "3", "summary": "Last generated version"}], "status": "final", "version": "3"}}, "product_tree": {"branches": [{"branches": [{"branches": [{"category": "product_name", "name": "Red Hat Satellite 6.18", "product": {"name": "Red Hat Satellite 6.18", "product_id": "Red Hat Satellite 6.18", "product_identification_helper": {"cpe": "cpe:/a:redhat:satellite:6.18::el9"}}}], "category": "product_family", "name": "Red Hat Satellite"}, {"branches": [{"category": "product_version", "name": "registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64", "product": {"name": "registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64", "product_id": "registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64", "product_identification_helper": {"purl": "pkg:oci/iop-advisor-frontend-rhel9@sha256%3A1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a?arch=amd64&repository_url=registry.redhat.io/satellite&tag=1777911535"}}}], "category": "architecture", "name": "amd64"}], "category": "vendor", "name": "Red Hat"}], "relationships": [{"category": "default_component_of", "full_product_name": {"name": "registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64 as a component of Red Hat Satellite 6.18", "product_id": "Red Hat Satellite 6.18:registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64"}, "product_reference": "registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64", "relates_to_product_reference": "Red Hat Satellite 6.18"}]}, "vulnerabilities": [{"cve": "CVE-2025-13465", "cwe": {"id": "CWE-1321", "name": "Improperly Controlled Modification of Object Prototype Attributes ('Prototype Pollution')"}, "discovery_date": "2026-01-21T20:01:28.774829+00:00", "ids": [{"system_name": "Red Hat Bugzilla ID", "text": "2431740"}], "notes": [{"category": "description", "text": "A flaw was found in Lodash. A prototype pollution vulnerability in the _.unset and _.omit functions allows an attacker able to control property paths to delete methods from global prototypes. By removing essential functionalities, this can result in a denial of service.", "title": "Vulnerability description"}, {"category": "summary", "text": "lodash: prototype pollution in _.unset and _.omit functions", "title": "Vulnerability summary"}, {"category": "other", "text": "This issue is only exploitable by applications using the _.unset and _.omit functions on an object and allowing user input to determine the path of the property to be removed. This issue only allows the deletion of properties but does not allow overwriting their behavior, limiting the impact to a denial of service. Due to this reason, this vulnerability has been rated with an important severity.

In Grafana, JavaScript code runs only in the browser, while the server side is all Golang. Therefore, the worst-case scenario is a loss of functionality in the client application inside the browser. To reflect this, the CVSS availability metric and the severity of the Grafana and the Grafana-PCP component have been updated to low and moderate, respectively.

The lodash dependency is bundled and used by the pcs-web-ui component of the PCS package. In Red Hat Enterprise Linux 8.10, the pcs-web-ui component is no longer included in the PCS package. As a result, RHEL 8.10 does not ship the vulnerable lodash component within PCS and is therefore not-affected by this CVE.", "title": "Statement"}, {"category": "general", "text": "The CVSS score(s) listed for this vulnerability do not reflect the associated product's status, and are included for informational purposes to better understand the severity of this vulnerability.", "title": "CVSS score applicability"}], "product_status": {"fixed": ["Red Hat Satellite 6.18:registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64"]}, "references": [{"category": "self", "summary": "Canonical URL", "url": "https://access.redhat.com/security/cve/CVE-2025-13465"}, {"category": "external", "summary": "RHBZ#2431740", "url": "https://bugzilla.redhat.com/show_bug.cgi?id=2431740"}, {"category": "external", "summary": "https://www.cve.org/CVERecord?id=CVE-2025-13465", "url": "https://www.cve.org/CVERecord?id=CVE-2025-13465"}, {"category": "external", "summary": "https://nvd.nist.gov/vuln/detail/CVE-2025-13465", "url": "https://nvd.nist.gov/vuln/detail/CVE-2025-13465"}, {"category": "external", "summary": "https://github.com/lodash/lodash/security/advisories/GHSA-xxjr-mmjv-4gpg", "url": "https://github.com/lodash/lodash/security/advisories/GHSA-xxjr-mmjv-4gpg"}], "release_date": "2026-01-21T19:05:28.846000+00:00", "remediations": [{"category": "vendor_fix", "date": "2026-05-07T15:45:54+00:00", "details": "For Red Hat Lightspeed in Satellite installation see the Red Hat Satellite documentation.", "product_ids": ["Red Hat Satellite 6.18:registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64"], "restart_required": {"category": "none"}, "url": "https://access.redhat.com/errata/RHSA-2026:14870"}, {"category": "workaround", "details": "To mitigate this issue, implement strict input validation before passing any property paths to the _.unset and _.omit functions to block attempts to access the prototype chain. Ensure that strings like __proto__, constructor and prototype are blocked, for example.", "product_ids": ["Red Hat Satellite 6.18:registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64"]}], "scores": [{"cvss_v3": {"attackComplexity": "LOW", "attackVector": "NETWORK", "availabilityImpact": "HIGH", "baseScore": 8.2, "baseSeverity": "HIGH", "confidentialityImpact": "NONE", "integrityImpact": "LOW", "privilegesRequired": "NONE", "scope": "UNCHANGED", "userInteraction": "NONE", "vectorString": "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:L/A:H", "version": "3.1"}, "products": ["Red Hat Satellite 6.18:registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64"]}], "threats": [{"category": "impact", "details": "Important"}], "title": "lodash: prototype pollution in _.unset and _.omit functions"}, {"cve": "CVE-2026-4800", "cwe": {"id": "CWE-94", "name": "Improper Control of Generation of Code ('Code Injection')"}, "discovery_date": "2026-03-31T20:01:21.918257+00:00", "ids": [{"system_name": "Red Hat Bugzilla ID", "text": "2453496"}], "notes": [{"category": "description", "text": "A flaw was found in lodash. The fix for CVE-2021-23337 added validation for the variable option in _.template but did not apply the same validation to options.imports key names. Both paths flow into the same Function() constructor sink. Additionally, _.template uses assignInWith to merge imports, which enumerates inherited properties via for..in. If Object.prototype has been polluted by any other vector, the polluted keys are copied into the imports object and passed to Function().", "title": "Vulnerability description"}, {"category": "summary", "text": "lodash: lodash: Arbitrary code execution via untrusted input in template imports", "title": "Vulnerability summary"}, {"category": "other", "text": "In the context of Red Hat Enterprise Linux, the grafana and grafana-pcp packages execute the affected JavaScript entirely client-side within the user's browser. Consequently, the attack surface is strictly restricted to the local browser environment.", "title": "Statement"}, {"category": "general", "text": "The CVSS score(s) listed for this vulnerability do not reflect the associated product's status, and are included for informational purposes to better understand the severity of this vulnerability.", "title": "CVSS score applicability"}], "product_status": {"fixed": ["Red Hat Satellite 6.18:registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64"]}, "references": [{"category": "self", "summary": "Canonical URL", "url": "https://access.redhat.com/security/cve/CVE-2026-4800"}, {"category": "external", "summary": "RHBZ#2453496", "url": "https://bugzilla.redhat.com/show_bug.cgi?id=2453496"}, {"category": "external", "summary": "https://www.cve.org/CVERecord?id=CVE-2026-4800", "url": "https://www.cve.org/CVERecord?id=CVE-2026-4800"}, {"category": "external", "summary": "https://nvd.nist.gov/vuln/detail/CVE-2026-4800", "url": "https://nvd.nist.gov/vuln/detail/CVE-2026-4800"}, {"category": "external", "summary": "https://cna.openjsf.org/security-advisories.html", "url": "https://cna.openjsf.org/security-advisories.html"}, {"category": "external", "summary": "https://github.com/advisories/GHSA-35jh-r3h4-6jhm", "url": "https://github.com/advisories/GHSA-35jh-r3h4-6jhm"}, {"category": "external", "summary": "https://github.com/lodash/lodash/commit/3469357cff396a26c363f8c1b5a91dde28ba4b1c", "url": "https://github.com/lodash/lodash/commit/3469357cff396a26c363f8c1b5a91dde28ba4b1c"}], "release_date": "2026-03-31T19:25:55.987000+00:00", "remediations": [{"category": "vendor_fix", "date": "2026-05-07T15:45:54+00:00", "details": "For Red Hat Lightspeed in Satellite installation see the Red Hat Satellite documentation.", "product_ids": ["Red Hat Satellite 6.18:registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64"], "restart_required": {"category": "none"}, "url": "https://access.redhat.com/errata/RHSA-2026:14870"}, {"category": "workaround", "details": "Mitigation for this issue is either not available or the currently available options do not meet the Red Hat Product Security criteria comprising ease of use and deployment, applicability to widespread installation base or stability.", "product_ids": ["Red Hat Satellite 6.18:registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64"]}], "scores": [{"cvss_v3": {"attackComplexity": "HIGH", "attackVector": "NETWORK", "availabilityImpact": "HIGH", "baseScore": 8.1, "baseSeverity": "HIGH", "confidentialityImpact": "HIGH", "integrityImpact": "HIGH", "privilegesRequired": "NONE", "scope": "UNCHANGED", "userInteraction": "NONE", "vectorString": "CVSS:3.1/AV:N/AC:H/PR:N/UI:N/S:U/C:H/I:H/A:H", "version": "3.1"}, "products": ["Red Hat Satellite 6.18:registry.redhat.io/satellite/iop-advisor-frontend-rhel9@sha256:1a9489fdc27626a7942f7406beae9994fe94b877010e2c7ff6077db880c7b52a_amd64"]}], "threats": [{"category": "impact", "details": "Important"}], "title": "lodash: lodash: Arbitrary code execution via untrusted input in template imports"}]}
